-- Double quotes are identifiers, single quotes are string literals
SELECT "order", 'pending' FROM "order";

-- MySQL and MariaDB spell identifiers with backticks by default
SELECT `order`, 'pending' FROM `order`;

-- SQL Server brackets the same idea, and doubles a quote to escape it
SELECT [order], 'it''s pending' FROM [order];

-- Keywords are case insensitive, string comparisons are not
select id from customers where email = 'Ana@Example.com';

-- SELECT * is fine at a prompt, list the columns in application code
SELECT * FROM products;
SELECT id, name, price_cents FROM products;

-- Aliases rename the output column and shorten the table reference
SELECT p.name AS product, p.price_cents / 100.0 AS price
FROM products AS p;

-- DISTINCT removes duplicate rows after projection
SELECT DISTINCT country FROM customers;

-- LIMIT and OFFSET are the PostgreSQL, MySQL, SQLite and MariaDB form
SELECT id, name FROM products ORDER BY name LIMIT 20 OFFSET 40;

-- Paging needs a tiebreaker or rows repeat between pages
SELECT id, name FROM products ORDER BY name, id LIMIT 20 OFFSET 40;

INSERT INTO customers (email, name, country)
VALUES ('ana@example.com', 'Ana Ribeiro', 'BR'),
       ('joao@example.com', 'Joao Silva', 'BR');

-- Insert the result of a query instead of literals
INSERT INTO customers_archive (id, email, deleted_at)
SELECT id, email, NOW() FROM customers WHERE deleted_at IS NOT NULL;

-- RETURNING hands back generated keys in the same statement
INSERT INTO orders (customer_id, total_cents)
VALUES (42, 12990)
RETURNING id, created_at;

-- MySQL has no RETURNING: read LAST_INSERT_ID() in the same session
INSERT INTO orders (customer_id, total_cents) VALUES (42, 12990);
SELECT LAST_INSERT_ID();

DELETE FROM sessions WHERE expires_at < NOW();

-- Delete through a subquery rather than a multi-table join
DELETE FROM orders
WHERE customer_id IN (SELECT id FROM customers WHERE deleted_at IS NOT NULL);

-- TRUNCATE is faster, resets identity in PostgreSQL and takes no WHERE
TRUNCATE TABLE staging_events;

ALTER TABLE customers ADD COLUMN phone TEXT;
ALTER TABLE customers ALTER COLUMN name SET NOT NULL;
ALTER TABLE customers RENAME COLUMN phone TO phone_number;
ALTER TABLE customers DROP COLUMN phone_number;

-- Copy the shape and the rows at once
CREATE TABLE customers_2025 AS
SELECT * FROM customers WHERE created_at < DATE '2026-01-01';

DROP TABLE IF EXISTS staging_events;

-- Name the constraint so a later migration can drop it by name
ALTER TABLE orders
  ADD CONSTRAINT orders_total_positive CHECK (total_cents >= 0);

-- Composite unique: one review per customer and product
ALTER TABLE reviews
  ADD CONSTRAINT reviews_customer_product_key UNIQUE (customer_id, product_id);

CREATE INDEX orders_customer_id_idx ON orders (customer_id);
CREATE INDEX orders_created_at_idx ON orders (created_at DESC);

-- Functional index: makes WHERE lower(email) = 'ana@example.com' seek
CREATE UNIQUE INDEX customers_email_lower_idx ON customers (lower(email));

-- Composite: equality columns first, range or sort column last
CREATE INDEX orders_customer_status_idx ON orders (customer_id, status);

-- Partial: only the rows the hot query reads
CREATE INDEX orders_pending_idx ON orders (created_at) WHERE status = 'pending';

-- Covering: the index alone answers the query, PostgreSQL 11 and later
CREATE INDEX orders_customer_covering_idx ON orders (customer_id) INCLUDE (total_cents);

-- Read the plan, not the wall clock alone
EXPLAIN ANALYZE
SELECT id, total_cents FROM orders
WHERE customer_id = 42 ORDER BY created_at DESC LIMIT 10;

-- Drop an index that no longer earns its write cost
DROP INDEX IF EXISTS orders_created_at_idx;

BEGIN;
UPDATE accounts SET balance_cents = balance_cents - 5000 WHERE id = 1;
UPDATE accounts SET balance_cents = balance_cents + 5000 WHERE id = 2;
COMMIT;

BEGIN;
DELETE FROM order_items WHERE order_id = 900;
SAVEPOINT after_items;
DELETE FROM orders WHERE id = 900;
ROLLBACK TO SAVEPOINT after_items;
COMMIT;

-- Read committed is the default; repeatable read holds one snapshot
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT SUM(balance_cents) FROM accounts;
COMMIT;

-- Lock the row for the rest of the transaction before read-modify-write
SELECT * FROM accounts WHERE id = 1 FOR UPDATE;

-- NULL is unknown, so it is never equal or unequal to anything
SELECT id FROM orders WHERE shipped_at IS NULL;
SELECT id FROM orders WHERE shipped_at IS NOT NULL;

-- This returns no rows, on every engine: use IS NULL instead
SELECT id FROM orders WHERE shipped_at = NULL;

-- Aggregates ignore NULLs, so AVG divides by the non-null count
SELECT COUNT(*) AS rows, COUNT(rating) AS rated, AVG(rating) AS average
FROM reviews;

-- PostgreSQL, SQLite and Oracle accept NULLS LAST
SELECT id, rating FROM reviews ORDER BY rating DESC NULLS LAST;

-- Row limit: LIMIT is PostgreSQL, MySQL, SQLite; TOP is SQL Server
SELECT id FROM orders ORDER BY created_at DESC LIMIT 10;
SELECT TOP 10 id FROM orders ORDER BY created_at DESC;

-- Oracle and SQL Server 2012 and later also take the standard form
SELECT id FROM orders ORDER BY created_at DESC FETCH FIRST 10 ROWS ONLY;

-- Concatenation: || is standard, CONCAT() is portable, + is SQL Server only
SELECT first_name || ' ' || last_name AS full_name FROM customers;
SELECT CONCAT(first_name, ' ', last_name) AS full_name FROM customers;

-- Current time: NOW() in PostgreSQL and MySQL, always CURRENT_TIMESTAMP
SELECT NOW(), CURRENT_TIMESTAMP;

-- Auto increment: IDENTITY is standard, SERIAL is PostgreSQL, AUTO_INCREMENT is MySQL
CREATE TABLE invoices (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY);
CREATE TABLE tickets  (id SERIAL PRIMARY KEY);
CREATE TABLE events   (id BIGINT AUTO_INCREMENT PRIMARY KEY);

-- Booleans: PostgreSQL has a real type, MySQL stores TINYINT(1)
SELECT id FROM customers WHERE active = TRUE;
